alter table public.integration_events add column if not exists next_retry_at timestamptz; alter table public.integration_events add column if not exists claimed_at timestamptz; alter table public.integration_events add column if not exists claim_attempt integer not null default 0; create index if not exists integration_events_retry_idx on public.integration_events (status, next_retry_at asc) where status in ('retry','pending'); create or replace function public.claim_integration_event(p_event_id uuid) returns boolean language plpgsql security definer set search_path=public as $$ declare v_status text; begin select status into v_status from public.integration_events where id=p_event_id for update; if not found then return false; end if; if v_status not in ('pending','retry','received','processing') then return false; end if; update public.integration_events set status='processing', claimed_at=now(), claim_attempt=claim_attempt+1 where id=p_event_id; return true; end; $$; revoke execute on function public.claim_integration_event(uuid) from public, anon, authenticated; grant execute on function public.claim_integration_event(uuid) to service_role;